/* @autogenerated */
import { escapeData, renderTemplate } from './template-render';

describe('renderTemplate', () => {
  const context = { lang: 'es-ES', translate: (key: string) => 'T(' + key + ')' };

  it('fills the template, iterating children', async () => {
    const md = await renderTemplate(
      '# {{name}}\n{{#each sites}}- {{name}} ({{floors.length}})\n{{/each}}',
      {
        name: 'ACME',
        sites: [
          { name: 'Madrid', floors: [1, 2] },
          { name: 'Vigo', floors: [] },
        ],
      },
      context,
    );
    expect(md).toBe('# ACME\n- Madrid (2)\n- Vigo (0)\n');
  });

  it('escapes the markdown of the data but not the one of the template', async () => {
    const md = await renderTemplate('| **{{a}}** | {{b}} |', { a: 'x|y', b: '*z*' }, context);
    expect(md).toBe('| **x\\|y** | \\*z\\* |');
  });

  it('formats dates and numbers with the language', async () => {
    const md = await renderTemplate(
      '{{date when}} · {{number total 2}} · {{number missing}}',
      { when: new Date(2026, 10, 6), total: 1234.5 },
      context,
    );
    expect(md).toBe(
      `${new Intl.DateTimeFormat('es-ES', { dateStyle: 'medium' }).format(new Date(2026, 10, 6))} · 1234,50 · `,
    );
  });

  it('translates keys, also built from the data', async () => {
    const md = await renderTemplate(
      "{{t 'common.ok'}} {{t (concat 'status.' status)}}",
      { status: 'IN_PROGRESS' },
      context,
    );
    expect(md).toBe('T(common.ok) T(status.IN\\_PROGRESS)');
  });

  it('offers @now and @lang at any level', async () => {
    const md = await renderTemplate('{{#each items}}{{@lang}} {{#if @now}}ok{{/if}}{{/each}}', { items: [1] }, context);
    expect(md).toBe('es-ES ok');
  });

  it('offers default, eq, join and sort', async () => {
    const md = await renderTemplate(
      "{{default missing '—'}} {{#if (eq a 1)}}uno{{/if}} {{join tags ' / '}} {{#each (sort items 'n')}}{{n}}{{/each}}",
      { a: 1, tags: ['x', 'y'], items: [{ n: 'b' }, { n: 'a' }] },
      context,
    );
    expect(md).toBe('— uno x / y ab');
  });
});

describe('escapeData', () => {
  it('escapes strings at any depth and keeps dates, numbers and cycles', () => {
    const when = new Date();
    const data: any = { name: 'a_b', when, total: 3, nested: [{ text: '#1' }] };
    data.self = data;
    const escaped = escapeData(data) as any;
    expect(escaped.name).toBe('a\\_b');
    expect(escaped.when).toBe(when);
    expect(escaped.total).toBe(3);
    expect(escaped.nested[0].text).toBe('\\#1');
    expect(escaped.self).toBe(escaped);
  });
});
